<div id="cf-cancel-modal" class="cfmoney-overlay" hidden role="dialog" aria-modal="true" aria-labelledby="cf-cancel-title"><div class="cfmoney-box"><header><div><h2 id="cf-cancel-title">Cancel File Processing</h2><p data-cancel-person></p></div><button type="button" data-cancel-close>×</button></header><form><div class="cfmoney-body"><p data-cancel-error role="alert" hidden></p><div data-cancel-inputs class="cfmoney-grid"><label class="cfmoney-full">Vendor-approved processing refund<input name="vendor_refund" type="number" min="0" step="0.01" required></label><label class="cfmoney-full">Who bears the remaining processing penalty?<select name="bearer" required><option value="">Choose every time</option><option value="client">Agent / Client pays</option><option value="company">Company bears</option></select></label><label>Posting date<input name="occurred_on" type="date" value="{{ now()->toDateString() }}" required></label><label>Reason<input name="note" maxlength="1000"></label></div><p data-cancel-preview class="cfmoney-help" style="white-space:pre-line"></p><p class="cfmoney-help">Package reversal only—not deletion. Previous charges, payments and refunds remain. Independent services are not refunded automatically; refund each service separately. Cash settlements happen in Party Statement.</p></div><footer><button type="button" data-cancel-back hidden>← Edit</button><button type="submit">Review cancellation →</button><button type="button" data-cancel-confirm hidden style="background:#dc3545;color:white">Confirm & cancel file</button><button type="button" data-cancel-close>Close</button></footer></form></div></div>
<script>
(()=>{
 const modal=document.getElementById('cf-cancel-modal'),form=modal.querySelector('form');let info,meta,url,token,busy=false,focus;
 const error=text=>{const el=modal.querySelector('[data-cancel-error]');el.textContent=text;el.hidden=!text},money=n=>'৳'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2});
 const stage=review=>{modal.querySelector('[data-cancel-inputs]').hidden=review;form.querySelector('[type=submit]').hidden=review;modal.querySelector('[data-cancel-confirm]').hidden=!review;modal.querySelector('[data-cancel-back]').hidden=!review};
 const calc=()=>{const refund=Number(form.elements.vendor_refund.value||0),penalty=meta.refunded?0:Number(meta.processing)-refund,delta=-Number(meta.package)+(form.elements.bearer.value==='client'?penalty:0);return{refund,penalty,charge:Number(info.charge)+delta,cost:Number(info.cost)-refund}};
 const preview=()=>{const c=calc();modal.querySelector('[data-cancel-preview]').textContent=`Package reversal: ${money(meta.package)}\nVendor refund now: ${money(c.refund)}\nNew processing penalty: ${money(c.penalty)}\nAfter cancellation — Charge ${money(c.charge)} · Cost ${money(c.cost)} · Profit ${money(c.charge-c.cost)}\n${meta.refunded?'Processing refund / penalty already posted; neither will be posted again. Previous adjustments remain.':'Agent bears: penalty added alongside package reversal. Company bears: no new agent penalty.'}`};
 document.addEventListener('click',event=>{const button=event.target.closest('[data-cf-cancel]');if(!button||busy)return;const root=button.closest('[data-cf-money-info]');info=JSON.parse(root.dataset.cfMoneyInfo);meta=JSON.parse(button.dataset.cfCancel);url=root.dataset.cfMoneyUrl;focus=button;const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const h=[...bytes].map(b=>b.toString(16).padStart(2,'0')).join('');token=h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);form.reset();form.elements.vendor_refund.value=0;form.elements.vendor_refund.readOnly=meta.refunded;form.elements.vendor_refund.max=meta.refunded?0:meta.processing;modal.querySelector('[data-cancel-person]').textContent=info.name+' · '+info.number;error('');stage(false);preview();modal.hidden=false;form.elements.vendor_refund.focus()},true);
 form.addEventListener('input',preview);form.addEventListener('change',preview);form.onsubmit=event=>{event.preventDefault();if(!busy&&form.reportValidity()){error('');preview();stage(true)}};
 modal.querySelector('[data-cancel-back]').onclick=()=>{if(!busy)stage(false)};modal.querySelectorAll('[data-cancel-close]').forEach(button=>button.onclick=()=>{if(!busy){modal.hidden=true;focus?.focus()}});
 modal.querySelector('[data-cancel-confirm]').onclick=async()=>{if(busy)return;busy=true;const button=modal.querySelector('[data-cancel-confirm]');button.disabled=true;try{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({...Object.fromEntries(new FormData(form)),type:'cancel',request_token:token})});const result=await response.json();if(!response.ok||!result.success)throw Error(result.message||'Cancellation failed');location.reload()}catch(e){error(e.message);busy=false;button.disabled=false}};
 modal.onkeydown=event=>{if(event.key!=='Tab')return;const controls=[...modal.querySelectorAll('button,input,select')].filter(el=>!el.disabled&&el.getClientRects().length);if(event.shiftKey&&document.activeElement===controls[0]){event.preventDefault();controls.at(-1).focus()}else if(!event.shiftKey&&document.activeElement===controls.at(-1)){event.preventDefault();controls[0].focus()}};
})();
</script>
